        const cm = { R: comp(rt.rain), F: comp(rt.ft), W: rt.sat === null ? C.W : comp(rt.sat), V, S };
        const sc = Math.round(risk(cm) * 10) / 10;
        perModel[m] = { score: sc, tier: tierOf(sc), rain_ratio: r3(rt.rain), freeze_thaw_ratio: r3(rt.ft), saturation_ratio: r3(rt.sat), soil_from_ensemble: rt.sat === null };
        tiers.push(tierOf(sc));
      }
      const counts = {}; tiers.forEach(t => counts[t] = (counts[t] || 0) + 1);
      const maxAgree = Math.max(...Object.values(counts));
      agreement = (maxAgree === MODELS.length && okModels.length === MODELS.length) ? 'high' : (maxAgree >= 2 ? 'medium' : 'low');
    }
    if (complete) {
      const ab = (arch && arch.base) || {};
      const hz = {}, status = {};
      const drvs = [['Extreme-rain days', pctInt(rr), W.R * C.R], ['Freeze-thaw days', pctInt(fr), W.F * C.F], ['Wet-soil days', pctInt(sr), W.W * C.W]].sort((a, b) => b[2] - a[2]);
      const localTop = W.V * C.V >= W.S * C.S ? 'Plant cover -' + r3(trend.drop) + ' NDVI in 5 years' : 'Slope ' + r1(slopePct) + '%';
      hz.ground = { key: 'ground', label: 'Ground failure', score: groundScore,
        why: drvs[0][2] > Math.max(W.V * C.V, W.S * C.S) ? drvs[0][0] + ' ' + sgn(drvs[0][1]) + '%' : (Math.max(W.V * C.V, W.S * C.S) > 0 ? localTop : 'No change from baseline') };
      status.ground = 'scored';
      // Drought
      const fD = { drySoil: comp(dryR), drySpell: comp(spellR) };
      const dS = weighted(fD, HAZ_W.drought);
      if (dS === null) status.drought = 'unavailable: ' + (!Number.isFinite(ab.spell) ? 'this cell was cached before dry-soil and dry-spell metrics were added, refetch it' : 'no climate model provided soil moisture or rain for this window');
      else {
        const pSoil = pctInt(dryR), pSpell = pctInt(spellR);
        hz.drought = { key: 'drought', label: 'Drought', score: dS, factors: fD,
          why: pSoil !== null && (pSpell === null || Math.abs(pSoil) >= Math.abs(pSpell)) ? 'Dry-soil days ' + sgn(pSoil) + '%' : 'Longest dry spell ' + sgn(pSpell) + '%',
          change: { drySoil: pSoil, drySpell: pSpell },
          base: { drySoilDaysPerYr: r1(ab.dry), drySpellDays: r1(ab.spell) },
          proj: { drySoilDaysPerYr: dryR !== null && Number.isFinite(ab.dry) ? r1(dryR * ab.dry) : null, drySpellDays: spellR !== null && Number.isFinite(ab.spell) ? r1(spellR * ab.spell) : null } };
        status.drought = dryR === null ? 'scored on dry spells only: no model soil moisture' : 'scored';
      }
      // Wildfire weather
      if (fireR === null || !Number.isFinite(ab.fire)) status.wildfire = 'unavailable: ' + (!Number.isFinite(ab.fire) ? 'no observed humidity in the cached baseline' : 'no climate model provided humidity for this window');
      else {
        const projF = fireR * ab.fire;
        const nm = (series || []).map(p => p.mean).filter(Number.isFinite);
        const ndviMean = nm.length ? nm.reduce((a, b) => a + b, 0) / nm.length : null;
        const fF = { change: clamp01((fireR - 1) / 2), level: clamp01(projF / FIRE_DAYS_FULL), fuel: ndviMean === null ? null : clamp01((ndviMean - 0.3) / 0.4) };
        hz.wildfire = { key: 'wildfire', label: 'Wildfire weather', score: weighted(fF, HAZ_W.wildfire), factors: fF,
          why: 'Fire-weather days ' + r1(ab.fire) + ' to ' + r1(projF) + ' a year (' + sgn(pctInt(fireR)) + '%)',
          change: { fireDays: pctInt(fireR) }, base: { fireWeatherDaysPerYr: r1(ab.fire) }, proj: { fireWeatherDaysPerYr: r1(projF) },
          fuelNdvi: ndviMean === null ? null : Math.round(ndviMean * 100) / 100, models_with_humidity: fireModels.length };
        status.wildfire = 'scored (' + fireModels.length + ' of ' + okModels.length + ' models have humidity)';
      }
      // River crossing: only where a mapped waterway crosses the centreline
      let xs = null;
      if (s.crossings_json !== null && s.crossings_json !== undefined) { try { const p = JSON.parse(s.crossings_json); if (Array.isArray(p)) xs = p; } catch (err) { xs = null; } }
      if (xs === null) status.crossing = 'not checked: no waterway map loaded for this segment';
      else if (!xs.length) status.crossing = 'not applicable: no mapped waterway crosses this segment';
      else {
        const size = Math.max(...xs.map(x => CROSSING_SIZE[x.kind] !== undefined ? CROSSING_SIZE[x.kind] : 0.4));
        const flows = xs.map(x => x.peakFlowM3s).filter(Number.isFinite);
        const peak = flows.length ? Math.max(...flows) : null;
        const fX = { size, rain: C.R, flow: peak === null ? null : clamp01(peak / PEAK_FLOW_FULL) };
        const big = xs.reduce((a, x) => ((CROSSING_SIZE[x.kind] || 0) > (CROSSING_SIZE[a.kind] || 0) ? x : a), xs[0]);
        hz.crossing = { key: 'crossing', label: 'River crossing', score: weighted(fX, HAZ_W.crossing), factors: fX,
          why: 'Crosses ' + (big.name || 'a ' + big.kind) + (peak !== null ? ' (peak flow ' + Math.round(peak) + ' m³/s)' : '') + ', heavy rain ' + sgn(pctInt(rr)) + '%',
          crossings: xs.map(x => ({ name: x.name || null, kind: x.kind, peakFlowM3s: Number.isFinite(x.peakFlowM3s) ? x.peakFlowM3s : null, at: x.at || null })) };
        status.crossing = peak === null ? 'scored without river flow: no discharge data at the crossing' : 'scored';
      }
      let top = hz.ground;
      for (const k of Object.keys(hz)) { hz[k].tier = tierOf(hz[k].score); if (hz[k].score > top.score) top = hz[k]; }
      score = top.score; tier = tierOf(score); topKey = top.key;
      hazardsJson = JSON.stringify({ top: topKey, ground_score: groundScore, hazards: hz, status,
        base: { drySoilDaysPerYr: r1(ab.dry), drySpellDays: r1(ab.spell), fireWeatherDaysPerYr: r1(ab.fire) },
        crossings: xs, ratio_full: RATIO_FULL, tiers: { amber: AMBER, red: RED } });
    }
    const pctTxt = x => x === null ? 'n/a' : ((x >= 1 ? '+' : '') + Math.round((x - 1) * 100) + '%');
    const facts = complete ? [
      'Segment ' + s.segment_index + ' (' + s.segment_id + '), ' + h.years + '-year horizon ' + h.start + '-' + h.end + ':',
      'risk score ' + score + '/100 (' + tier + '), set by the worst hazard: ' + topKey + '. Ground-failure score ' + groundScore + '. CMIP6 model agreement ' + agreement + '.',
      'Extreme rain days ' + pctTxt(rr) + ' vs ' + baselineRow.baseline_period + ' baseline;',
      'freeze-thaw days ' + pctTxt(fr) + ';',
      'soil saturation days ' + pctTxt(sr) + ';',
      'Sentinel-2 growing-season NDVI drop ' + r3(trend.drop) + ' over ' + trend.years[0] + '-' + trend.years[trend.years.length - 1] + ';',
      'terrain slope ' + r1(slopePct) + '%.',
    ].join(' ') : '';

    out.push({ json: {
      prediction_id: s.segment_id + '_h' + h.years,
      segment_id: s.segment_id,
      corridor_id: s.corridor_id,
      segment_index: s.segment_index,
      horizon_years: h.years,
      window_start: h.start + '-01-01',
      window_end: h.end + '-12-31',
      risk_score: score,
      tier,
      hazard: topKey,
      ground_score: groundScore,
      hazards_json: hazardsJson,
      model_agreement: agreement,
      score_r: r3(C.R), score_f: r3(C.F), score_w: r3(C.W), score_v: r3(C.V), score_s: r3(C.S),
      rain_ratio: r3(rr), freeze_thaw_ratio: r3(fr), saturation_ratio: r3(sr),
      model_scores_json: JSON.stringify(perModel),
      explanation: '',
      needs_explanation: tier === 'amber' || tier === 'red',
      explain_facts: facts,
      archive_hash: cell.archive_hash || '', climate_hash: cell.climate_hash || '',
      ndvi_hash: ndviHash, elevation_hash: e.ok ? e.hash : '',
      segment_source_hash: s.segment_source_hash,
      status: complete ? 'verified' : 'unverified',
      error_message: hErrors.join('; '),
      computed_at: now,
      baseline_row: h.years === 5 ? baselineRow : null,
    } });
  });
});

// Attach provenance rows to the first item (logged once by the audit branch)
const seen = new Set();
const srcRows = sourceRows.filter(r => { const k = r.source_kind + '|' + r.source_url; if (seen.has(k)) return false; seen.add(k); return true; })
  .map(r => Object.assign({ corridor_id: cfg.corridor_id, fetched_at: now, segment_count: segs.length, fallback_reason: r.source_kind === 'cdse_sentinel2_ndvi' && r.batch_status === 'failed' ? 'live NDVI failed; previous live series used if cached, else segment unverified' : '' }, r));
if (out.length) out[0].json.source_rows = srcRows;
return out;

